  return (
    <View testID="moldura-fundo" style={[styles.fill, styles.center, { backgroundColor: colors.surface }]}>
      <View
        testID="moldura"
        style={[
          styles.frame,
          {
            height: Math.min(height, FRAME_MAX_HEIGHT),
            backgroundColor: colors.bg,
            borderColor: colors.line,
          },
        ]}
      >
        {children}
      </View>
    </View>
  );
}

